WITH unpacked AS (SELECT id, host, log_ts, level, COALESCE(context['version'], 'none') AS version_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id FROM app_logs WHERE log_ts < '2023-06-01') SELECT *, NTILE(4) OVER (PARTITION BY level ORDER BY duration_sec, id) AS duration_sec_bucket, LEAD(duration_sec, 2) OVER (PARTITION BY host ORDER BY duration_sec, id) AS next_duration_sec FROM unpacked;
